-- Pickup and packing workflow. PostgreSQL equivalent of SQL Server script 018.
BEGIN;
CREATE TABLE "PickupStatuses"("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,"Id" UUID NOT NULL UNIQUE,"TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"),"Code" VARCHAR(40) NOT NULL,"Name" VARCHAR(120) NOT NULL,"DisplayOrder" INTEGER NOT NULL,"Color" VARCHAR(30),"IsCompleted" BOOLEAN NOT NULL,"IsActive" BOOLEAN NOT NULL,UNIQUE("TenantId","Code"));
CREATE TABLE "Vehicles"("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,"Id" UUID NOT NULL UNIQUE,"TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"),"RegistrationNumber" VARCHAR(40) NOT NULL,"Name" VARCHAR(120) NOT NULL,"Type" VARCHAR(80) NOT NULL,"CapacityCbm" NUMERIC(12,3) NOT NULL,"DriverName" VARCHAR(120),"DriverPhone" VARCHAR(40),"IsActive" BOOLEAN NOT NULL,UNIQUE("TenantId","RegistrationNumber"));
CREATE TABLE "Pickups"("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,"Id" UUID NOT NULL UNIQUE,"TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"),"PickupNumber" VARCHAR(40) NOT NULL,"QuotationId" UUID REFERENCES "Quotations"("Id"),"CustomerName" VARCHAR(160) NOT NULL,"Phone" VARCHAR(40) NOT NULL,"Email" VARCHAR(254),"Address" VARCHAR(500) NOT NULL,"Latitude" NUMERIC(10,7),"Longitude" NUMERIC(10,7),"ScheduledAtUtc" TIMESTAMPTZ NOT NULL,"ConfirmedAtUtc" TIMESTAMPTZ,"StatusId" UUID NOT NULL REFERENCES "PickupStatuses"("Id"),"VehicleId" UUID REFERENCES "Vehicles"("Id"),"Notes" VARCHAR(2000),"ConfirmationTokenHash" VARCHAR(64) UNIQUE,"ConfirmationExpiresAtUtc" TIMESTAMPTZ,"CreatedAtUtc" TIMESTAMPTZ NOT NULL,"UpdatedAtUtc" TIMESTAMPTZ NOT NULL,UNIQUE("TenantId","PickupNumber"));
CREATE TABLE "PickupAssignments"("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,"Id" UUID NOT NULL UNIQUE,"TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"),"PickupId" UUID NOT NULL REFERENCES "Pickups"("Id") ON DELETE CASCADE,"EmployeeId" UUID NOT NULL REFERENCES "Employees"("Id"),"Role" VARCHAR(80) NOT NULL);
CREATE TABLE "PickupPackages"("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,"Id" UUID NOT NULL UNIQUE,"TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"),"PickupId" UUID NOT NULL REFERENCES "Pickups"("Id") ON DELETE CASCADE,"BoxTypeId" UUID NOT NULL REFERENCES "BoxTypes"("Id"),"TrackingNumber" VARCHAR(80) NOT NULL,"Notes" VARCHAR(500),UNIQUE("TenantId","TrackingNumber"));
CREATE TABLE "PickupPackageItems"("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,"Id" UUID NOT NULL UNIQUE,"TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"),"PickupPackageId" UUID NOT NULL REFERENCES "PickupPackages"("Id") ON DELETE CASCADE,"ItemName" VARCHAR(160) NOT NULL,"Quantity" INTEGER NOT NULL,"Notes" VARCHAR(500));
CREATE TABLE "PickupMaterialUsages"("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,"Id" UUID NOT NULL UNIQUE,"TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"),"PickupId" UUID NOT NULL REFERENCES "Pickups"("Id") ON DELETE CASCADE,"MaterialId" UUID NOT NULL REFERENCES "PackingMaterials"("Id"),"Quantity" NUMERIC(12,3) NOT NULL,"UnitCost" NUMERIC(18,2) NOT NULL);
CREATE TABLE "PickupTransactions"("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,"Id" UUID NOT NULL UNIQUE,"TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"),"PickupId" UUID NOT NULL REFERENCES "Pickups"("Id") ON DELETE CASCADE,"TransactionNumber" VARCHAR(60) NOT NULL,"Type" VARCHAR(20) NOT NULL,"Category" VARCHAR(120) NOT NULL,"Amount" NUMERIC(18,2) NOT NULL,"PaymentMethod" VARCHAR(40) NOT NULL,"Notes" VARCHAR(500),"CreatedAtUtc" TIMESTAMPTZ NOT NULL,UNIQUE("TenantId","TransactionNumber"));
INSERT INTO "PickupStatuses"("Id","TenantId","Code","Name","DisplayOrder","Color","IsCompleted","IsActive") SELECT gen_random_uuid(),t."Id",v.code,v.name,v.ord,v.color,v.done,TRUE FROM "Tenants" t CROSS JOIN (VALUES('PLANNED','Planned',10,'blue',FALSE),('CONFIRMED','Customer Confirmed',20,'cyan',FALSE),('PACKING','Packing',30,'orange',FALSE),('PICKED_UP','Picked Up',40,'green',TRUE))v(code,name,ord,color,done);
COMMIT;
